use super::*;

/// Measure the behavioural axes over a set of events. PURE — no clock, no store, no filesystem.
pub fn measure_behaviour(events: &[Event]) -> Behaviour {
    Behaviour {
        dists: vec![
            tally(
                HOUR_OF_DAY,
                "which UTC hours this person works in (an EMPTY hour is the strongest reading here)",
                // Descriptive until measured. Available instantly and probably strong — but a
                // timezone change shifts every category at once, so it has to earn promotion.
                Kind::Descriptive,
                events.iter().filter_map(|e| hour_of(e.at_ms)),
            ),
            tally(
                WEEKDAY,
                "which days of the week they work",
                Kind::Descriptive,
                events.iter().filter_map(|e| weekday_of(e.at_ms)),
            ),
            tally(
                PROJECT,
                "which projects they work in, and how the work is spread across them",
                Kind::Descriptive,
                events.iter().filter(|e| !e.project.trim().is_empty()).map(|e| e.project.clone()),
            ),
        ],
        events: events.len() as u64,
    }
}
